package org.babyfish.jimmer.sql.filter;

import org.babyfish.jimmer.sql.ast.query.Sortable;
import org.babyfish.jimmer.sql.ast.query.SubQueryProvider;
import org.babyfish.jimmer.sql.ast.table.Props;
import org.jetbrains.annotations.NotNull;

/**
 * @param <P> The EntityProps type generated by apt
 */
public interface FilterArgs<P extends Props> extends Sortable, SubQueryProvider {

    @NotNull
    P getTable();

    /**
     * 当前被过滤的表,是不是用户主动查询的那张表 —— 而不是顺着关联拿到的表。
     *
     * <p>它让一个内部混合了多种条件的过滤器,可以选择只把其中一部分作用在根表上。
     *
     * <p>典型场景是多租户模型里还带一个「当前站在哪个组织上看」的维度:
     * 这些条件决定数据可见性,应该作用在根表上;而顺着根表读出来的行,
     * 是业务发生时产生的记录。
     *
     * <p>组织 A 发起的申请单,完全可能引用组织 B 名下的资质 —— B2B2C 里
     * 这是业务常态,不是泄漏。再过滤一遍保护不了什么(能看到申请单就已经
     * 拿到了这份数据),只会让已经发生的事实读不出来:引用字段可空,
     * 于是**静默变 null** —— 接口照样 200,节点却消失。
     *
     * <p>可见性属于根表。读到一条引用,前提本来就已经有权访问拥有它的那一行。
     *
     * <p>只要表有父表就返回 {@code false} —— 这样同时覆盖两种下钻形态:
     * data loader 另发的一条查询,以及 join 进用户语句里的表。
     *
     * @see org.babyfish.jimmer.sql.ast.impl.table.TableImplementor#getParent()
     */
    default boolean isRootQuery() {
        return true;
    }
}
